/**
 * BadgerPreview — reusable badger sprite with colored glow aura.
 *
 * Used in the lobby panel (color indicator) and potentially elsewhere.
 * Plays the player's authored idle animation with the same outer glow as the arena.
 * Optionally tracks the mouse pointer for rotation.
 */
import * as Phaser from 'phaser';
import { PLAYER_SIZE, PLAYER_VISUAL_SCALE } from '../config';
import { BADGER_IDLE_FRAME, BADGER_WALKING_TEXTURE_KEY, syncBadgerWalkingAnimation } from '../animations/BadgerAnimations';
import { HeldItemVisual } from '../entities/HeldItemVisual';
import { removeInternalFx, type GlowHandle } from '../utils/phaserFx';
import { addPlayerGlow, PLAYER_GLOW_STRENGTH } from '../effects/PlayerGlow';

const ROTATION_OFFSET = Math.PI / 2;

export class BadgerPreview {
  readonly sprite: Phaser.GameObjects.Sprite;

  private glowFx: GlowHandle | null = null;
  private glowTween: Phaser.Tweens.Tween | null = null;
  private colorHex: number;
  private readonly heldItem: HeldItemVisual;
  private heldItemVisible = true;

  constructor(
    private scene: Phaser.Scene,
    x: number,
    y: number,
    color: number,
    displaySize = PLAYER_SIZE,
    /** Aufbaupfad-Arbeit fuer das erst spaet erzeugte Item-Bild, z.B. die Klarheitskamera. */
    onHeldItemCreated?: (image: Phaser.GameObjects.Image) => void,
  ) {
    this.colorHex = color;

    this.sprite = scene.add.sprite(x, y, BADGER_WALKING_TEXTURE_KEY, BADGER_IDLE_FRAME);
    this.sprite.setDisplaySize(displaySize * PLAYER_VISUAL_SCALE, displaySize * PLAYER_VISUAL_SCALE);
    syncBadgerWalkingAnimation(this.sprite, false);

    // Dieselbe Zuordnung wie in der Arena, nur mit der groesseren Vorschau-Kantenlaenge: die
    // Waffe skaliert damit automatisch mit, statt eine zweite Groessenpflege zu brauchen.
    this.heldItem = new HeldItemVisual(scene, 0, onHeldItemCreated);
    this.glowFx = addPlayerGlow(this.sprite, color);
    if (this.glowFx) {
      this.glowTween = scene.tweens.add({
        targets:       this.glowFx,
        outerStrength: { from: PLAYER_GLOW_STRENGTH.min, to: PLAYER_GLOW_STRENGTH.max },
        duration:      1000,
        yoyo:          true,
        repeat:        -1,
        ease:          'Sine.easeInOut',
      });
    }
  }

  /** Change the glow color. */
  setColor(color: number): void {
    if (color === this.colorHex) return;
    this.colorHex = color;
    if (this.glowFx) this.glowFx.color = color;
  }

  /**
   * Loadout-Item, das die Vorschau in den Pfoten haelt. `null` blendet es aus.
   * In der Lobby zeigt das den zuletzt geaenderten Slot.
   */
  setHeldItemId(itemId: string | null): void {
    this.heldItem.setItem(itemId);
    this.syncHeldItem();
  }

  /** Set rotation directly (radians, with offset applied). */
  setRotation(aimAngle: number): void {
    this.sprite.rotation = aimAngle + ROTATION_OFFSET;
    this.syncHeldItem();
  }

  setScrollFactor(factor: number): void {
    this.sprite.setScrollFactor(factor);
    this.heldItem.setScrollFactor(factor);
  }

  setDepth(depth: number): void {
    this.sprite.setDepth(depth);
    this.heldItem.setDepth(depth);
  }

  setPosition(x: number, y: number): void {
    this.sprite.setPosition(x, y);
    this.syncHeldItem();
  }

  /**
   * Sichtbarkeit inklusive Glow-Puls. Der Puls-Tween laeuft mit `repeat: -1` und wuerde sonst
   * waehrend eines ganzen Matches weiterlaufen und den Glow-Filter jeden Frame neu als dirty
   * markieren, obwohl die Vorschau unsichtbar ist. Rein optisch aendert das nichts: Der Puls
   * wird nur pausiert, solange ohnehin nichts zu sehen ist, und beim Einblenden fortgesetzt.
   */
  setVisible(visible: boolean): void {
    this.sprite.setVisible(visible);
    syncBadgerWalkingAnimation(this.sprite, false, visible);
    this.heldItemVisible = visible;
    this.syncHeldItem();
    if (visible) this.glowTween?.resume();
    else this.glowTween?.pause();
  }

  destroy(): void {
    this.glowTween?.stop();
    this.heldItem.destroy();
    removeInternalFx(this.sprite, this.glowFx);
    this.glowFx = null;
    this.sprite.destroy();
  }

  private syncHeldItem(): void {
    this.heldItem.sync(
      this.sprite.x,
      this.sprite.y,
      this.sprite.rotation,
      this.sprite.displayWidth,
      this.heldItemVisible,
    );
  }
}
